diff --git a/CHANGELOG.md b/CHANGELOG.md
index af3280492a..a4c58a6ff0 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -13,6 +13,14 @@ block a release again.

 ## Unreleased

+- fix(gh-1743): a structured compaction that hits its budget watchdog
+  (300s total, or a provider-level kill the engine cannot recover from)
+  no longer aborts the live session. `AutoCompactorFactory.run()` now
+  applies the mechanical local-trim fallback (keepRecentTokens,
+  pairing-repaired, `[context trimmed locally]` marker — the same valve
+  the classic pass ladder ends on) instead of failing fast; the honest
+  both-roles-failed verdict is kept only when nothing is droppable.
+
 - fix(gh-1636): auto-compaction stops dumping the internal checkpoint
   summary into the console — the default report is ONE marker line
   (`● auto-compacted · engine: N → M tokens (F freed · P%)`); the records
diff --git a/lib/src/agent/auto_compactor.dart b/lib/src/agent/auto_compactor.dart
index b6a162b46e..46a3c4fdd0 100644
--- a/lib/src/agent/auto_compactor.dart
+++ b/lib/src/agent/auto_compactor.dart
@@ -346,6 +346,35 @@ final class AutoCompactor {
     }
   }

+  /// gh-1743: host-callable emergency valve for a timed-out compaction —
+  /// applies the same mechanical local trim [_localTrimFallback] the
+  /// classic pass ladder ends on (keep the most recent
+  /// [CompactionSettings.keepRecentTokens], repair tool pairing, prefix
+  /// the `[context trimmed locally]` marker), fires the `local-trim` pass
+  /// receipt and closes the [AutoCompactorHooks.onDone] bracket exactly
+  /// like the `_runPass` trim branch, and reports whether the live
+  /// context was actually bounded. `false` means nothing was droppable —
+  /// the caller keeps its failure verdict.
+  bool applyLocalTrimFallback({int pass = 1}) {
+    final tokensBefore = _requestTokens();
+    final trimmed = _localTrimFallback();
+    if (trimmed == null) return false;
+    state.messages = trimmed.messages;
+    final tokensAfter = _requestTokens();
+    hooks.onPass(
+      AutoCompactorPass(
+        pass: pass,
+        tokensBefore: tokensBefore,
+        tokensAfter: tokensAfter,
+        fallback: 'local-trim',
+        ok: true,
+        droppedMessages: trimmed.dropped,
+      ),
+    );
+    hooks.onDone(pass, tokensAfter);
+    return true;
+  }
+
   /// Whether the smol summarizer is distinct from the main one and should be
   /// tried before falling back to main.
   bool _shouldRunFallback() {
@@ -989,9 +1018,17 @@ class AutoCompactorFactory {
       }
       if (outcome.timedOut) {
         // Budget kill (issue #515): the summarizer/judge wedged past the
-        // watchdog budget and the underlying call was aborted. Fail fast
-        // with the named error — re-running the classic engine here would
-        // only re-wedge the same endpoint.
+        // watchdog budget and the underlying call was aborted. gh-1743:
+        // do NOT abort the live session — re-running the classic engine
+        // here would only re-wedge the same endpoint, but the mechanical
+        // local trim needs no endpoint at all: bound the live context
+        // (keepRecentTokens, pairing-repaired, `[context trimmed locally]`
+        // marker) so the run proceeds. The failure verdict is kept only
+        // when there is nothing left to trim.
+        final trimmed = build().applyLocalTrimFallback(
+          pass: adapter.passCount + 1,
+        );
+        if (trimmed) return true;
         hooks.onBothRolesFailed(outcome.error!);
         return false;
       }
diff --git a/test/agent/auto_compactor_structured_budget_test.dart b/test/agent/auto_compactor_structured_budget_test.dart
index a47e67f4e4..0141b58af3 100644
--- a/test/agent/auto_compactor_structured_budget_test.dart
+++ b/test/agent/auto_compactor_structured_budget_test.dart
@@ -30,6 +30,7 @@ AssistantMessage _message(StopReason reason) => AssistantMessage(
 final class _CapturingHooks implements AutoCompactorHooks {
   Object? bothRolesError;
   final passes = <AutoCompactorPass>[];
+  int doneCount = 0;

   @override
   void onDelta(String delta) {}
@@ -44,7 +45,7 @@ final class _CapturingHooks implements AutoCompactorHooks {
   void onRetry(int attempt, int maxAttempts, Duration backoff, Object error) {}

   @override
-  void onDone(int passes, int tokens) {}
+  void onDone(int passes, int tokens) => doneCount++;

   @override
   void onBothRolesFailed(Object lastError) => bothRolesError = lastError;
@@ -400,4 +401,170 @@ void main() {
     final records = await session.getEntries();
     expect(records.whereType<CompactCheckpointRecord>(), isEmpty);
   });
+
+  /// gh-1743: a transcript over the window with a droppable read pair —
+  /// the shape the local trim can rescue.
+  Future<(Session, AgentState)> overWindowSessionWithDroppableTail() async {
+    final session = await repo.create(JsonlSessionCreateOptions(cwd: '/w'));
+    await session.appendMessage(UserMessage.text('fix the login crash'));
+    await session.appendMessage(
+      AssistantMessage(
+        content: [
+          const TextContent(text: 'looking'),
+          ToolCall(id: 'c1', name: 'read', arguments: const {}),
+        ],
+        api: 'test-api',
+        provider: 'test-provider',
+        model: 'test-model',
+        usage: Usage.zero,
+        stopReason: StopReason.stop,
+        timestamp: DateTime.utc(2026),
+      ),
+    );
+    await session.appendMessage(
+      ToolResultMessage(
+        toolCallId: 'c1',
+        toolName: 'read',
+        content: [TextContent(text: 'x' * 16000)],
+        isError: false,
+        timestamp: DateTime.utc(2026),
+      ),
+    );
+    for (var i = 0; i < 11; i++) {
+      await session.appendMessage(
+        AssistantMessage(
+          content: [TextContent(text: 'filler $i')],
+          api: 'test-api',
+          provider: 'test-provider',
+          model: 'test-model',
+          usage: Usage.zero,
+          stopReason: StopReason.stop,
+          timestamp: DateTime.utc(2026),
+        ),
+      );
+    }
+    final state = AgentState(
+      model: _model,
+      messages: await session.buildContextMessages(),
+    );
+    return (session, state);
+  }
+
+  test('gh-1743: a factory-level budget timeout (wedged judge past the '
+      'total budget) falls back to the local trim instead of aborting '
+      'the session', () async {
+    final (session, state) = await overWindowSessionWithDroppableTail();
+    final tokensBefore = estimateRequestTokens(
+      state.messages,
+      systemPrompt: state.systemPrompt,
+      tools: state.tools,
+    );
+    final tokensSeen = <CancelToken?>[];
+    final hooks = _CapturingHooks();
+
+    final ok = await AutoCompactorFactory(
+      session: session,
+      state: state,
+      window: 1000,
+      settings: settings,
+      sources: AutoCompactorSources(
+        smolStream: null,
+        smolModel: null,
+        // A judge stream that NEVER settles — not even on cancel — so
+        // the engine cannot recover within its own per-call ladder and
+        // the factory's totalBudget watchdog is what fires.
+        mainStream: (m, c, {cancelToken}) {
