  final smolModel = this.smolModel;

  final attempt = await _pickAttempt(
    pass,
    runFallback: runFallback,
    mainLabel: _modelLabel(mainModel),
    smolLabel: smolModel == null ? 'default' : _modelLabel(smolModel),
    clock: clock,
