        AutoCompactorPass(
          pass: pass,
          tokensBefore: tokensBefore,
          tokensAfter: tokensAfter,
          fallback: 'local-trim',
          ok: true,
          droppedMessages: trimmed.dropped,
        ),
      );
      hooks.onDone(pass, tokensAfter);
      return (
        done: true,
        success:
            !shouldCompact(tokensAfter, window, settings) &&
            !_overMessageCap(),
