    unawaited(
      cancelToken.onCancel.then((_) {
        stream.push(
          DoneEvent(
            reason: StopReason.aborted,
            message: _message(StopReason.aborted),
          ),
        );
        stream.end();
      }),
    );
  }
  return stream;
}

/// A summarizer that pends forever until its cancel token fires.
Future<SummarizationResult> _hangingSummarizer(
