    hooks.onPass(
      AutoCompactorPass(
        pass: pass,
        tokensBefore: tokensBefore,
        tokensAfter: tokensBefore,
        fallback: attempt.fallback,
        ok: true,
      ),
    );
    hooks.onDone(pass, tokensBefore);
    return (done: true, success: true);
