  /// Which summarizer was used: `'smol'`, `'main'`, or `null` when the
  /// pass was skipped (no work to do).
  final String? fallback;

  /// Whether the pass succeeded.
  final bool ok;

  /// The error that failed the pass, when [ok] is `false`.
