      smolStream,
      smolModel,
      prompts: prompts,
      onDelta: hooks.onDelta,
    );
    final mainSummarizer = streamFunctionSummarizer(
      sources.mainStream,
      sources.mainModel,
      prompts: prompts,
      onDelta: hooks.onDelta,
    );
    return AutoCompactor(
      session: session,
      state: state,
      window: window,
      settings: settings,
      summary: smolSummarizer,
      mainSummary: mainSummarizer,
