/// their watchdog budget expires — not pend forever, and not survive the
/// timeout as an abandoned zombie call.
const _model = Model(
  id: 'test-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: 100000,
